export const AUDIO_MAP = {
  south_male: SOUTH_MALE,
  south_female: SOUTH_FEMALE,
} as const;

export type VoiceDir = keyof typeof AUDIO_MAP;

export function lookupAudio(voiceDir: string, key: string): AssetSource | null {
  const table = (AUDIO_MAP as any)[voiceDir];
  if (!table) return null;
  return table[key] ?? null;
}
